const LEAD = [[0,"REST",0,1],[16,"A",0,1],[48,"A",0,1],[80,"A",0,1],[112,"A",0,1],[144,"REST",0,1],[272,"REST",0,1],[304,"REST",0,1],[320,"A",1,1],[352,"A",1,1],[384,"A",0,2]]
